#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<bool> visited(n + 1, false);

    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            vector<int> comp;
            long long sum_degrees = 0;

            // DFS para coletar todos os vértices da componente conexa
            vector<int> q;
            q.push_back(i);
            visited[i] = true;

            int head = 0;
            while (head < (int)q.size()) {
                int u = q[head++];
                comp.push_back(u);
                sum_degrees += adj[u].size();

                for (int v : adj[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        q.push_back(v);
                    }
                }
            }

            long long sz = comp.size();
            // Em um clique, a soma dos graus é exatamente sz * (sz - 1)
            if (sum_degrees < sz * (sz - 1)) {
                // Existe pelo menos um vértice com grau < sz - 1
                int u_target = -1;
                for (int u : comp) {
                    if ((int)adj[u].size() < sz - 1) {
                        u_target = u;
                        break;
                    }
                }

                vector<bool> is_neighbor(n + 1, false);
                for (int v : adj[u_target]) {
                    is_neighbor[v] = true;
                }
                is_neighbor[u_target] = true;

                for (int v : comp) {
                    if (!is_neighbor[v]) {
                        cout << u_target << " " << v << "\n";
                        return 0;
                    }
                }
            }
        }
    }

    cout << -1 << "\n";
    return 0;
}
